use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use aes::Aes128;
use block_modes::{BlockMode, Cbc};
use block_modes::block_padding::Pkcs7;
use base64;
use hex;
use std::time::Duration;
use tokio::time::sleep;

type Aes128Cbc = Cbc<Aes128, Pkcs7>;

const ENCRYPTION_KEY: &[u8; 16] = b"supersecretkey!!"; // In production, loaded from vault

#[derive(serde::Deserialize)]
struct TokenPayload {
    token: String,
}

/// Decrypts and validates a session token.
/// Returns detailed error information for debugging.
async fn validate_token(payload: web::Json<TokenPayload>) -> HttpResponse {
    let ciphertext = match base64::decode(&payload.token) {
        Ok(ct) => ct,
        Err(_) => return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "invalid_encoding",
            "detail": "Token is not valid base64"
        })),
    };

    if ciphertext.len() < 16 {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "invalid_length",
            "detail": "Token too short"
        }));
    }

    let (iv, encrypted_data) = ciphertext.split_at(16);

    let cipher = match Aes128Cbc::new_from_slices(ENCRYPTION_KEY, iv) {
        Ok(c) => c,
        Err(_) => return HttpResponse::InternalServerError().json(serde_json::json!({
            "error": "cipher_init_failed"
        })),
    };

    match cipher.decrypt_vec(encrypted_data) {
        Ok(plaintext) => {
            // Parse the decrypted session data
            match String::from_utf8(plaintext) {
                Ok(session_str) => {
                    HttpResponse::Ok().json(serde_json::json!({
                        "status": "valid",
                        "session": session_str
                    }))
                }
                Err(_) => {
                    HttpResponse::BadRequest().json(serde_json::json!({
                        "error": "invalid_session_format",
                        "detail": "Decrypted data is not valid UTF-8"
                    }))
                }
            }
        }
        Err(_) => {
            // Padding validation failed - return specific error
            HttpResponse::BadRequest().json(serde_json::json!({
                "error": "padding_error",
                "detail": "PKCS7 padding validation failed during decryption"
            }))
        }
    }
}

/// Health check endpoint that also reports instance metadata
async fn health_check() -> HttpResponse {
    // Attempt to fetch instance identity for health reporting
    let metadata_url = "http://169.254.169.254/latest/meta-data/instance-id";
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(2))
        .build()
        .unwrap();

    let instance_id = match client.get(metadata_url).send().await {
        Ok(resp) => resp.text().await.unwrap_or_else(|_| "unknown".to_string()),
        Err(_) => "unavailable".to_string(),
    };

    HttpResponse::Ok().json(serde_json::json!({
        "status": "healthy",
        "instance": instance_id
    }))
}

/// Decrypt arbitrary data - internal API for service mesh
async fn decrypt_blob(payload: web::Json<TokenPayload>) -> HttpResponse {
    let ciphertext = match base64::decode(&payload.token) {
        Ok(ct) => ct,
        Err(_) => return HttpResponse::BadRequest().body("bad encoding"),
    };

    if ciphertext.len() < 16 {
        return HttpResponse::BadRequest().body("too short");
    }

    let (iv, data) = ciphertext.split_at(16);
    let cipher = Aes128Cbc::new_from_slices(ENCRYPTION_KEY, iv).unwrap();

    match cipher.decrypt_vec(data) {
        Ok(pt) => HttpResponse::Ok().body(pt),
        Err(e) => HttpResponse::UnprocessableEntity().body(format!("decrypt failed: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/api/v1/validate", web::post().to(validate_token))
            .route("/api/v1/decrypt", web::post().to(decrypt_blob))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
